local a={error='ERROR',advertencia='ADVERTENCIA',informacion='INFO'}local b={error='^1',advertencia='^3',informacion='^5'}function Doctor.count(c)local d={error=0,advertencia=0,informacion=0}for e,f in ipairs(c)do d[f.severity]=d[f.severity]+1 end;return d end;function Doctor.sortFindings(c)table.sort(c,function(g,h)local i,j=Doctor.RANK[g.severity],Doctor.RANK[h.severity]if i~=j then return i<j end;if g.check~=h.check then return g.check<h.check end;return g.where<h.where end)end;function Doctor.summaryLines(k)local d=k.counts;local l={('^7NX_ServerDoctor · %d errores, %d advertencias, %d informaciones'):format(d.error,d.advertencia,d.informacion),('^7Comprobaciones: %s · %d recursos · %d archivos mirados · %d ms'):format(table.concat(k.checks,', '),k.resources,k.fileChecks,k.durationMs)}if#k.findings==0 then l[#l+1]='^2No se encontró ningún problema.'end;return l end;function Doctor.findingLines(f,m)local n=('%s[%s]^7 %s ^9(%s)'):format(b[f.severity],a[f.severity],f.title,f.where)local o=m=='completo'or m=='normal'and f.severity~='informacion'if m=='resumen'and f.severity=='informacion'then return{}end;if not o then return{n}end;local l={n}if f.why~=''then l[#l+1]='   Por qué importa: '..f.why end;for p,q in ipairs(f.fix)do if q and q~=''then l[#l+1]=('   %d) %s'):format(p,q)end end;return l end;function Doctor.reportLines(k,m)local l=Doctor.summaryLines(k)for e,f in ipairs(k.findings)do for e,r in ipairs(Doctor.findingLines(f,m))do l[#l+1]=r end end;for s,t in pairs(k.hidden)do l[#l+1]=('^9(%s: %d hallazgos más no mostrados; sube Config.Limits.findingsPerCheck para verlos)'):format(s,t)end;return l end